<script setup lang='ts'>import{ref,computed}from'vue';import{useExhibitionFlow}from'../composables/useExhibitionFlow';const{state,create,duplicate,release,togglePiece}=useExhibitionFlow();const selected=ref(state.value.exhibitions[0]?.id||'');const current=computed(()=>state.value.exhibitions.find((x:any)=>x.id===selected.value));const notice=ref('');const newTitle=ref('');function add(){try{const e=create(newTitle.value);selected.value=e.id;newTitle.value='';notice.value='已创建展览草稿'}catch(e:any){notice.value=e.message}}function pub(){try{release(selected.value);notice.value='展览已上线'}catch(e:any){notice.value=e.message}}function dup(){try{const e=duplicate(selected.value);selected.value=e.id;notice.value='已复制为新草稿「'+e.title+'」'}catch(err:any){notice.value=err.message}}</script><template><div class='studio'><header><div><p class='eyebrow'>CLAY / CURATION LAB</p><h1>陶艺展览策划台</h1><p class='intro'>把每件作品放进属于它的光线与距离里。</p></div><div class='header-note'>{{state.exhibitions.length}} 场展览 · {{state.artworks.length}} 件作品</div></header><main><section class='rail'><div class='new-box'><input v-model='newTitle' placeholder='新展览名称' @keyup.enter='add'><button @click='add'>创建草稿</button></div><div v-for='e in state.exhibitions' :key='e.id' class='exhibit-row' :class='{active:e.id===selected}' @click='selected=e.id'><div><span>{{e.status}}</span><h3>{{e.title}}</h3><p>{{e.subtitle}}</p></div><b>{{e.pieces.length}} 件</b></div></section><section class='canvas' v-if='current'><div class='canvas-top'><div><p class='eyebrow'>策展工作面</p><h2>{{current.title}}</h2><p>{{current.description}}</p></div><div class='actions'><button class='copy' @click='dup'>复制为草稿</button><button class='release' @click='pub'>上线展览</button></div></div><div class='meta'><span>策展人 · {{current.curator}}</span><span>{{current.opening}} — {{current.closing}}</span><span class='status'>{{current.status}}</span></div><div class='piece-grid'><div class='piece' v-for='a in state.artworks' :key='a.id' :class='{chosen:current.pieces.includes(a.id)}' @click='togglePiece(current.id,a.id)'><div class='piece-art' :style='{background:a.tone}'><span>{{a.year}}</span></div><div><h3>{{a.title}}</h3><p>{{a.artist}} · {{a.material}}</p><small>{{a.note}}</small></div><button>{{current.pieces.includes(a.id)?'已编排':'加入展览'}}</button></div></div><div class='notice' v-if='notice'>{{notice}}</div></section></main></div></template>
